package io.clipbridge.android;
import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;

public final class TransferService extends Service {
    private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();private JSONObject state;private final Map<String,MediaWire> clients=new HashMap<>();private final Map<String,JSONObject> remote=new HashMap<>();private final Map<String,Long> published=new HashMap<>(),nextPoll=new HashMap<>(),nextWrite=new HashMap<>(),nextTransfer=new HashMap<>();private final Set<String> errors=new HashSet<>();private long noticeUntil;private int attachmentInterval=3;private boolean restored;private String installation="";private NotificationManager notifications;private File cache;private volatile boolean running;
    public void onCreate(){super.onCreate();notifications=getSystemService(NotificationManager.class);StatusNotifications.ensure(this);notifications.createNotificationChannel(new NotificationChannel("transfers","文件与图片",NotificationManager.IMPORTANCE_DEFAULT));for(int old:new int[]{4102,4103,4104,4105,4106,4107,4108,4109})notifications.cancel(old);cache=new File(getFilesDir(),"transfers");cache.mkdirs();Notification ongoing=new Notification.Builder(this,"transfer-service-v2").setSmallIcon(io.clipbridge.android.R.drawable.ic_clipbridge_foreground).setContentTitle("ClipBridge 附件接收已开启").setContentText("等待图片和文件请求").setContentIntent(open()).setOngoing(true).build();if(Build.VERSION.SDK_INT>=34)startForeground(4100,ongoing,ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE);else startForeground(4100,ongoing);running=true;
        worker.execute(()->{try{state=new JSONObject(getContentResolver().call(BridgeProvider.URI,"attachment-load",null,null).getString("state"));}catch(Exception e){notice("附件状态无法读取，请检查本地数据。",4102);stopSelf();}});
        worker.schedule(this::poll,1,TimeUnit.SECONDS);
    }
    private void poll(){if(!running||state==null)return;try{if(!getContentResolver().call(BridgeProvider.URI,"profiles",null,null).getBoolean("paused"))new GroupController(this).tick(false);tick();if(noticeUntil>0&&System.currentTimeMillis()>noticeUntil){noticeUntil=0;notifications.notify(4100,new Notification.Builder(this,StatusNotifications.CHANNEL).setSmallIcon(io.clipbridge.android.R.drawable.ic_clipbridge_foreground).setContentTitle("ClipBridge 附件接收已开启").setContentText("等待图片和文件请求").setContentIntent(open()).setOnlyAlertOnce(true).setOngoing(true).build());}}catch(Throwable e){notice("附件连接暂不可用，稍后自动重试。",4103);}boolean busy=false;try{JSONArray jobs=state.getJSONArray("outgoing");for(int i=0;i<jobs.length();i++){JSONObject job=jobs.getJSONObject(i),uploaded=job.getJSONObject("uploaded");if(Set.of("done","rejected","cancelled").contains(job.optString("phase")))continue;java.util.Iterator<String> keys=uploaded.keys();while(keys.hasNext()){int count=uploaded.optInt(keys.next());if(count>0&&count<job.getJSONObject("offer").getInt("chunks"))busy=true;}}JSONArray incoming=state.getJSONArray("incoming");for(int i=0;i<incoming.length();i++){JSONObject item=incoming.getJSONObject(i);if(item.optString("phase").equals("accepted")&&item.optInt("downloaded")>0&&item.optInt("downloaded")<item.getJSONObject("offer").getInt("chunks"))busy=true;}}catch(Exception ignored){}if(running)worker.schedule(this::poll,busy?100:1000,TimeUnit.MILLISECONDS);}
    private void synced(String pair){try{JSONArray list=profiles();JSONObject p=profile(list,pair);if(p==null)return;JSONObject c=p.getJSONObject("config");Bundle b=new Bundle();b.putString("pair",pair);b.putString("device",c.getString("device"));b.putLong("lastSync",System.currentTimeMillis());getContentResolver().call(BridgeProvider.URI,"metrics",null,b);}catch(Exception ignored){}}
    public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null)worker.execute(()->{try{if(state==null)return;String action=intent.getStringExtra("action");if("decide".equals(action))decide(intent.getStringExtra("id"),intent.getBooleanExtra("accept",false));else if("stage".equals(action))stage(intent);else if("cancel".equals(action)){JSONArray jobs=state.getJSONArray("outgoing");for(int i=0;i<jobs.length();i++){JSONObject job=jobs.getJSONObject(i);if(!Set.of("done","rejected").contains(job.optString("phase"))){job.put("phase","cancelled");job.getJSONObject("offer").put("status","cancelled");new File(job.getString("path")).delete();}}save();published.clear();}}catch(Exception e){try{if("stage".equals(intent.getStringExtra("action"))){File source=new File(intent.getStringExtra("path"));if(source.getCanonicalPath().startsWith(new File(getCacheDir(),"share").getCanonicalPath()+File.separator))source.delete();}}catch(Exception ignored){}notice(e instanceof IllegalArgumentException?e.getMessage():"附件操作失败，请检查文件与连接。",4104);}});return START_STICKY;}
    public IBinder onBind(Intent intent){return null;}public void onDestroy(){running=false;worker.shutdownNow();super.onDestroy();}
    private PendingIntent open(){return PendingIntent.getActivity(this,4100,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private void save()throws Exception{getContentResolver().call(BridgeProvider.URI,"attachment-save",state.toString(),null);}
    private void notice(String text,int ignored){noticeUntil=System.currentTimeMillis()+10000;notifications.notify(4100,new Notification.Builder(this,"transfers").setSmallIcon(io.clipbridge.android.R.drawable.ic_clipbridge_foreground).setContentTitle("ClipBridge").setContentText(text).setContentIntent(open()).setOnlyAlertOnce(true).setOngoing(true).build());}
    private PendingIntent action(String id,boolean accept){Intent intent=new Intent(this,TransferActionReceiver.class).setData(Uri.parse("clipbridge-action://"+id+"/"+accept)).putExtra("id",id).putExtra("accept",accept);return PendingIntent.getBroadcast(this,(id+accept).hashCode(),intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private int notificationId(String id){return 10000+(id.hashCode()&0x3fffffff);}
    private void prompt(JSONObject item,boolean preview)throws Exception{JSONObject o=item.getJSONObject("offer");String id=o.getString("id");Notification.Builder builder=new Notification.Builder(this,"transfers").setSmallIcon(io.clipbridge.android.R.drawable.ic_clipbridge_foreground).setContentTitle(preview?"收到图片，是否保存到相册？":"文件接收请求").setContentText(o.getString("name")+" · "+String.format(java.util.Locale.ROOT,"%.2f MB",o.getLong("size")/1048576d)).setContentIntent(open()).setAutoCancel(false).addAction(new Notification.Action.Builder(null,preview?"✅ 保存":"✅ 接收",action(id,true)).build()).addAction(new Notification.Action.Builder(null,"❌ 拒绝",action(id,false)).build());
        if(preview){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(item.getString("path"),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0||(long)bounds.outWidth*bounds.outHeight>20000000)throw new IOException("Image dimensions unsupported");BitmapFactory.Options small=new BitmapFactory.Options();int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>1024)sample*=2;small.inSampleSize=sample;Bitmap bitmap=BitmapFactory.decodeFile(item.getString("path"),small);if(bitmap==null)throw new IOException();builder.setStyle(new Notification.BigPictureStyle().bigPicture(bitmap));}
        notifications.notify(notificationId(id),builder.build());
    }
    private JSONArray profiles()throws Exception{Bundle b=getContentResolver().call(BridgeProvider.URI,"profiles",null,null);int interval=Math.max(1,Math.min(300,b.getInt("attachmentPollSeconds",3)));if(interval!=attachmentInterval){attachmentInterval=interval;nextPoll.clear();}installation=b.getString("installation");if(b.getBoolean("paused"))return new JSONArray();JSONArray list=new JSONArray(b.getString("profiles")),active=new JSONArray();for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optBoolean("enabled",true))active.put(list.getJSONObject(i));return active;}
    private JSONObject profile(JSONArray profiles,String pair)throws Exception{for(int i=0;i<profiles.length();i++){JSONObject p=profiles.getJSONObject(i);if(p.getJSONObject("config").getString("pair").equals(pair))return p;}return null;}
    private boolean contains(JSONArray values,String value)throws Exception{for(int i=0;i<values.length();i++)if(value.equals(values.getString(i)))return true;return false;}
    private void add(JSONArray values,String value)throws Exception{if(!contains(values,value))values.put(value);}
    private JSONObject find(JSONArray array,String id)throws Exception{for(int i=0;i<array.length();i++){JSONObject row=array.getJSONObject(i);if(row.getJSONObject("offer").getString("id").equals(id))return row;}return null;}
    private void decide(String id,boolean accept)throws Exception{Protocol.id(id);JSONObject item=find(state.getJSONArray("incoming"),id);if(item==null)return;if(item.optString("phase").equals("done")||item.optString("phase").equals("rejected"))return;
        if(!item.optString("phase").equals("preview")&&item.getJSONObject("offer").getLong("expires")<=System.currentTimeMillis()/1000){accept=false;notice("文件请求已过期，请让对方重新发送。",4103);}if(accept&&item.optString("phase").equals("preview")){saveReceived(item,true);return;}item.put("phase",accept?"accepted":"rejected");if(!accept)new File(item.optString("path")).delete();save();published.clear();notifications.cancel(notificationId(id));}
    private long used(){long bytes=0;File[] files=cache.listFiles();if(files!=null)for(File file:files)bytes+=file.length();return bytes;}
    private void stage(Intent intent)throws Exception{String path=intent.getStringExtra("path"),name=MediaProtocol.safe(intent.getStringExtra("name")),kind=intent.getStringExtra("kind");File source=new File(path);if(!source.getCanonicalPath().startsWith(new File(getCacheDir(),"share").getCanonicalPath()+File.separator))throw new SecurityException();if(used()+source.length()>512L*1024*1024)throw new IllegalArgumentException("附件暂存已接近 512 MB，请先处理已有传输。");if(source.length()>MediaProtocol.MAX)throw new IllegalArgumentException("单文件上限 100 MB，请使用其他大文件传输方式。");JSONArray targets=new JSONArray(intent.getStringExtra("targets"));JSONArray jobs=state.getJSONArray("outgoing");int pending=0;for(int i=0;i<jobs.length();i++)if(!Set.of("done","rejected","cancelled").contains(jobs.getJSONObject(i).optString("phase")))pending++;if(pending>=20)throw new IllegalArgumentException("待发送附件过多，请先完成或取消。");String id=UUID.randomUUID().toString().replace("-","");File staged=new File(cache,id+".send");MessageDigest digest=MessageDigest.getInstance("SHA-256");long size=0;try(InputStream input=new FileInputStream(source);OutputStream output=new FileOutputStream(staged)){byte[] buffer=new byte[MediaProtocol.CHUNK];int n;while((n=input.read(buffer))!=-1){size+=n;if(size>MediaProtocol.MAX)throw new IllegalArgumentException("文件超过 100 MB，请使用其他传输方式。");digest.update(buffer,0,n);output.write(buffer,0,n);}}catch(Exception e){staged.delete();throw e;}
        profiles();JSONObject offer=new JSONObject().put("id",id).put("name",name).put("mime",kind.equals("image")?"image/png":"application/octet-stream").put("kind",kind).put("size",size).put("hash",MediaProtocol.hex(digest.digest())).put("chunks",Math.max(1,(size+MediaProtocol.CHUNK-1)/MediaProtocol.CHUNK)).put("expires",System.currentTimeMillis()/1000+3600).put("status","offered").put("sender",installation);MediaProtocol.validate(offer);JSONObject chosen=targets.length()>0?profile(profiles(),targets.getString(0)):null;String target=chosen==null?"":chosen.optString("groupKey").isEmpty()?chosen.optString("peerIdentity"):"trusted:"+chosen.getString("groupKey");if(!target.startsWith("trusted:")&&target.length()!=32&&targets.length()>0)target=targets.getString(0);jobs.put(new JSONObject().put("target",target).put("offer",offer).put("path",staged.getAbsolutePath()).put("pairs",targets).put("uploaded",new JSONObject()).put("phase","waiting").put("route",0));save();published.clear();source.delete();notice(kind.equals("file")?"文件请求已排队，等待对方同意。":"图片已加入发送队列。",4105);
    }
    private void progress(String title,int done,int total){noticeUntil=System.currentTimeMillis()+10000;notifications.notify(4100,new Notification.Builder(this,"transfers").setSmallIcon(io.clipbridge.android.R.drawable.ic_clipbridge_foreground).setContentTitle(title).setProgress(total,done,false).setOnlyAlertOnce(true).setOngoing(true).setContentIntent(open()).build());}
    private void tick()throws Exception{JSONArray active=profiles();if(active.length()==0){if(!new GroupController(this).active())stopSelf();return;}long now=System.currentTimeMillis()/1000;JSONArray outgoing=state.getJSONArray("outgoing"),incoming=state.getJSONArray("incoming");
        for(int i=0;i<incoming.length();i++){JSONObject expired=incoming.getJSONObject(i);if(expired.getJSONObject("offer").getLong("expires")<=now&&Set.of("waiting","accepted").contains(expired.optString("phase"))){expired.put("phase","rejected");new File(expired.optString("path")).delete();notifications.cancel(notificationId(expired.getJSONObject("offer").getString("id")));published.clear();}}
        if(!restored){for(int i=0;i<incoming.length();i++){JSONObject item=incoming.getJSONObject(i);if(item.optString("phase").equals("waiting"))prompt(item,false);else if(item.optString("phase").equals("preview")){if(item.getJSONObject("offer").getString("kind").equals("image"))prompt(item,true);else saveReceived(item,false);}}restored=true;}
        for(int i=0;i<active.length();i++){JSONObject p=active.getJSONObject(i),c=p.getJSONObject("config");String pair=c.getString("pair");try{if(now<nextTransfer.getOrDefault(pair,0L))continue;MediaWire wire=clients.get(pair);if(wire==null){wire=new MediaWire(c);clients.put(pair,wire);}if(now<nextPoll.getOrDefault(pair,0L))continue;nextPoll.put(pair,now+attachmentInterval);JSONObject index=wire.index();if(profile(profiles(),pair)==null)continue;errors.remove(pair);if(index!=null){remote.put(pair,index);JSONArray offers=index.getJSONArray("offers");for(int n=0;n<offers.length();n++){JSONObject offer=offers.getJSONObject(n);if(offer.getLong("expires")<=now || p.optString("peerIdentity").length()==32&&!offer.getString("sender").equals(p.optString("peerIdentity")))continue;JSONObject item=find(incoming,offer.getString("id"));if(item==null){int count=0;for(int j=0;j<incoming.length();j++)if(!Set.of("done","rejected").contains(incoming.getJSONObject(j).optString("phase")))count++;if(count>=32)continue;item=new JSONObject().put("offer",offer).put("pairs",new JSONArray()).put("phase",offer.getString("kind").equals("image")?"accepted":"waiting").put("downloaded",0);incoming.put(item);save();if(offer.getString("kind").equals("file"))prompt(item,false);}else if(!item.getJSONObject("offer").getString("sender").equals(offer.getString("sender")))continue;add(item.getJSONArray("pairs"),pair);if(offer.getString("status").equals("cancelled")&&!Set.of("done","rejected").contains(item.optString("phase"))){item.put("phase","rejected");new File(item.optString("path")).delete();notifications.cancel(notificationId(offer.getString("id")));published.clear();}}}}catch(Exception e){remote.remove(pair);nextPoll.put(pair,now+(c.optString("transport").equals("webdav")?300:10));if(errors.add(pair))notice(c.optString("transport").equals("webdav")?"WebDAV 附件暂不可用，请检查权限或限频；5 分钟后重试。":"附件通道不可用，请检查或更新专用中转。",4103);}}
        for(int i=0;i<outgoing.length();i++){JSONObject job=outgoing.getJSONObject(i),offer=job.getJSONObject("offer");String id=offer.getString("id"),phase=job.optString("phase");if(Set.of("done","rejected","cancelled").contains(phase))continue;if(offer.getLong("expires")<=now){job.put("phase","cancelled");offer.put("status","cancelled");new File(job.getString("path")).delete();published.clear();continue;}JSONArray pairs=job.getJSONArray("pairs");String target=job.optString("target");for(int g=0;g<active.length();g++){JSONObject candidate=active.getJSONObject(g);String key=candidate.getJSONObject("config").getString("pair"),group=candidate.optString("groupKey").isEmpty()?candidate.optString("peerIdentity"):"trusted:"+candidate.getString("groupKey");if(!group.startsWith("trusted:")&&group.length()!=32)group=key;if(contains(pairs,key)&&target.equals(key)&&(!candidate.optString("groupKey").isEmpty()||candidate.optString("peerIdentity").length()==32)){target=group;job.put("target",target);}if(target.equals(group))add(pairs,key);}
            List<String> routes=new ArrayList<>();List<String> decisions=new ArrayList<>();for(int n=0;n<pairs.length();n++){String pair=pairs.getString(n);if(profile(active,pair)==null)continue;routes.add(pair);JSONObject index=remote.get(pair);if(index!=null){JSONArray receipt=index.getJSONArray("decisions");for(int j=0;j<receipt.length();j++)if(id.equals(receipt.getJSONObject(j).getString("id")))decisions.add(receipt.getJSONObject(j).getString("status"));}}if(routes.isEmpty())continue;if(decisions.contains("done")||decisions.contains("rejected")){job.put("phase",decisions.contains("done")?"done":"rejected");new File(job.getString("path")).delete();notice(decisions.contains("done")?"对方已接收："+offer.getString("name"):"对方已拒绝："+offer.getString("name"),4107);continue;}
            if(offer.getString("kind").equals("file")&&!decisions.contains("accepted")){if(routes.size()>1&&now-job.optLong("offeredAt")>=120){job.put("route",job.optInt("route")+1).put("offeredAt",now);published.clear();}continue;}
            String pair=routes.get(Math.floorMod(job.optInt("route"),routes.size()));try{if(now<nextTransfer.getOrDefault(pair,0L))continue;MediaWire wire=clients.get(pair);if(wire==null)throw new IOException();JSONObject uploaded=job.getJSONObject("uploaded");int part=uploaded.optInt(pair);try(RandomAccessFile file=new RandomAccessFile(job.getString("path"),"r")){file.seek((long)part*MediaProtocol.CHUNK);if(profile(active,pair).getJSONObject("config").optString("transport").equals("webdav")&&part<offer.getInt("chunks")){wire.putBundle(new File(job.getString("path")),offer);uploaded.put(pair,offer.getInt("chunks"));}else for(int batch=0;batch<32&&part<offer.getInt("chunks")&&running;batch++,part++){if(profile(profiles(),pair)==null)break;int length=(int)Math.min(MediaProtocol.CHUNK,offer.getLong("size")-file.getFilePointer());byte[] plain=new byte[length];file.readFully(plain);wire.put(id,part,plain);uploaded.put(pair,part+1);progress("发送 "+offer.getString("name"),part+1,offer.getInt("chunks"));}}if(uploaded.optInt(pair)==offer.getInt("chunks")&&!offer.getString("status").equals("ready")){offer.put("status","ready");job.put("phase","ready");synced(pair);published.clear();}}catch(Exception e){nextTransfer.put(pair,now+(profile(active,pair).getJSONObject("config").optString("transport").equals("webdav")?300:10));job.put("route",job.optInt("route")+1);offer.put("status","offered");published.clear();}}
        for(int i=0;i<incoming.length();i++){JSONObject item=incoming.getJSONObject(i),offer=item.getJSONObject("offer");if(!item.optString("phase").equals("accepted")||offer.getLong("expires")<=now)continue;String id=offer.getString("id");JSONArray pairs=item.getJSONArray("pairs");for(int n=0;n<pairs.length();n++){String pair=pairs.getString(n);if(profile(active,pair)==null||now<nextTransfer.getOrDefault(pair,0L))continue;JSONObject index=remote.get(pair);if(index==null)continue;boolean ready=false;JSONArray offers=index.getJSONArray("offers");for(int j=0;j<offers.length();j++)if(id.equals(offers.getJSONObject(j).getString("id"))&&offers.getJSONObject(j).getString("status").equals("ready"))ready=true;if(!ready)continue;
                try{if(item.optInt("downloaded")==0 && used()+offer.getLong("size")>512L*1024*1024){notice("附件暂存不足，请先处理待保存图片或取消任务。",4103);continue;}File path=new File(cache,offer.getString("sender")+"-"+id+".receive");if(!path.getAbsolutePath().equals(item.optString("path"))){item.put("path",path.getAbsolutePath()).put("downloaded",0);}int part=item.optInt("downloaded");try(RandomAccessFile output=new RandomAccessFile(path,"rw")){if(part==0)output.setLength(0);output.seek((long)part*MediaProtocol.CHUNK);if(profile(active,pair).getJSONObject("config").optString("transport").equals("webdav")){output.close();clients.get(pair).getBundle(offer,path);item.put("downloaded",offer.getInt("chunks"));}else for(int batch=0;batch<32&&part<offer.getInt("chunks")&&running;batch++,part++){if(profile(profiles(),pair)==null)break;byte[] data=clients.get(pair).get(id,part);int length=(int)Math.min(MediaProtocol.CHUNK,offer.getLong("size")-(long)part*MediaProtocol.CHUNK);if(data.length!=length)throw new SecurityException();output.write(data);item.put("downloaded",part+1);progress("接收 "+offer.getString("name"),part+1,offer.getInt("chunks"));}if(!profile(active,pair).getJSONObject("config").optString("transport").equals("webdav"))output.getFD().sync();}if(item.optInt("downloaded")==offer.getInt("chunks")){MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream input=new FileInputStream(path)){byte[] buffer=new byte[8192];int length;while((length=input.read(buffer))!=-1)hash.update(buffer,0,length);}if(path.length()!=offer.getLong("size")||!MediaProtocol.hex(hash.digest()).equals(offer.getString("hash")))throw new SecurityException();item.put("phase","preview").put("sourcePair",pair);save();if(offer.getString("kind").equals("image"))prompt(item,true);else saveReceived(item,false);}break;
                }catch(Exception e){nextTransfer.put(pair,now+(profile(active,pair).getJSONObject("config").optString("transport").equals("webdav")?300:10));item.put("downloaded",0);new File(item.optString("path")).delete();}}
        }
        for(int i=0;i<active.length();i++){JSONObject p=active.getJSONObject(i);String pair=p.getJSONObject("config").getString("pair");if(now<nextWrite.getOrDefault(pair,0L)||now-published.getOrDefault(pair,0L)<(p.getJSONObject("config").optString("transport").equals("webdav")?900:30))continue;try{JSONArray offers=new JSONArray(),decisions=new JSONArray();List<JSONObject> ordered=new ArrayList<>();for(int j=0;j<outgoing.length();j++)ordered.add(outgoing.getJSONObject(j));ordered.sort(Comparator.comparingInt(j->j.optString("phase").equals("cancelled")?1:0));for(int j=0;j<ordered.size();j++){JSONObject job=ordered.get(j),offer=new JSONObject(job.getJSONObject("offer").toString());if(!contains(job.getJSONArray("pairs"),pair)||offer.getLong("expires")<=now||Set.of("done","rejected").contains(job.optString("phase")))continue;if(offer.getString("status").equals("ready")&&job.getJSONObject("uploaded").optInt(pair)<offer.getInt("chunks"))offer.put("status","offered");if(offers.length()<32)offers.put(offer);}for(int j=incoming.length()-1;j>=0;j--){JSONObject item=incoming.getJSONObject(j),offer=item.getJSONObject("offer");String phase=item.optString("phase");if(contains(item.getJSONArray("pairs"),pair)&&offer.getLong("expires")>now&&!phase.equals("waiting"))if(decisions.length()<128)decisions.put(new JSONObject().put("id",offer.getString("id")).put("status",Set.of("done","rejected").contains(phase)?phase:"accepted"));}clients.get(pair).index(new JSONObject().put("offers",offers).put("decisions",decisions));published.put(pair,now);}catch(Exception ignored){nextWrite.put(pair,now+(p.getJSONObject("config").optString("transport").equals("webdav")?300:10));notice("附件通知上传失败，稍后重试。",4103);}}
        for(int i=0;i<outgoing.length();i++){JSONObject job=outgoing.getJSONObject(i);if(!Set.of("done","rejected","cancelled").contains(job.optString("phase")))continue;JSONObject uploaded=job.getJSONObject("uploaded"),cleaned=job.optJSONObject("cleaned");if(cleaned==null){cleaned=new JSONObject();job.put("cleaned",cleaned);}Iterator<String> keys=uploaded.keys();while(keys.hasNext()){String pair=keys.next();if(profile(active,pair)==null||!clients.containsKey(pair))continue;int count=cleaned.optInt(pair);try{for(int batch=0;batch<32&&count<uploaded.optInt(pair);batch++,count++){clients.get(pair).delete(job.getJSONObject("offer").getString("id"),count);cleaned.put(pair,count+1);}}catch(Exception ignored){}}}
        for(int i=outgoing.length()-1;i>=0;i--)if(outgoing.getJSONObject(i).getJSONObject("offer").getLong("expires")<now-86400){new File(outgoing.getJSONObject(i).optString("path")).delete();outgoing.remove(i);}for(int i=incoming.length()-1;i>=0;i--)if(incoming.getJSONObject(i).getJSONObject("offer").getLong("expires")<now-86400){notifications.cancel(notificationId(incoming.getJSONObject(i).getJSONObject("offer").getString("id")));new File(incoming.getJSONObject(i).optString("path")).delete();incoming.remove(i);}save();
    }
    private void saveReceived(JSONObject item,boolean image)throws Exception{JSONObject offer=item.getJSONObject("offer");Uri destination=item.has("destination")?Uri.parse(item.getString("destination")):null;try{
            if(destination==null){ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,MediaProtocol.safe(offer.getString("name")));values.put(MediaStore.MediaColumns.MIME_TYPE,image?"image/png":offer.getString("mime"));values.put(MediaStore.MediaColumns.RELATIVE_PATH,(image?Environment.DIRECTORY_PICTURES:Environment.DIRECTORY_DOWNLOADS)+"/ClipBridge");values.put(MediaStore.MediaColumns.IS_PENDING,1);destination=getContentResolver().insert(image?MediaStore.Images.Media.EXTERNAL_CONTENT_URI:MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);if(destination==null)throw new IOException();item.put("destination",destination.toString());save();}
            try(InputStream input=new FileInputStream(item.getString("path"));OutputStream output=getContentResolver().openOutputStream(destination,"w")){if(output==null)throw new IOException();byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);}
            ContentValues done=new ContentValues();done.put(MediaStore.MediaColumns.IS_PENDING,0);getContentResolver().update(destination,done,null,null);item.put("phase","done");synced(item.optString("sourcePair"));save();published.clear();new File(item.getString("path")).delete();Intent view=new Intent(this,OpenReceivedActivity.class).setData(destination).putExtra("mime",image?"image/png":offer.getString("mime")).putExtra("name",offer.getString("name"));PendingIntent openFile=PendingIntent.getActivity(this,notificationId(offer.getString("id")),view,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
            notifications.notify(notificationId(offer.getString("id")),new Notification.Builder(this,"transfers").setSmallIcon(io.clipbridge.android.R.drawable.ic_clipbridge_foreground).setContentTitle(offer.getString("name")).setContentText(image?"已保存到相册 · 点击打开":"接收完成 · 点击打开文件").setContentIntent(openFile).setAutoCancel(true).setOnlyAlertOnce(true).build());notice("接收完成",4108);
        }catch(Exception e){if(destination!=null)getContentResolver().delete(destination,null,null);item.remove("destination");save();notice("保存失败，请检查存储空间后重试。",4109);}}
}
